<template><ElSpace direction="vertical" fill class="v1-page" :size="20"><ElPageHeader title="天枢" content="后端设置" @back="$emit('navigate','overview')" />
 <ElCard v-if="!system.owner_configured" shadow="never"><ElButton type="primary" @click="openForm('owner')">建立管理员</ElButton></ElCard>
 <ElTabs v-model="tab" type="border-card">
  <ElTabPane label="空间与计费" name="space"><ElDescriptions :column="2" border><ElDescriptionsItem label="空间">{{space.name}}</ElDescriptionsItem><ElDescriptionsItem label="月度预算">{{n(space.tariff.monthly_budget,0)}} 元</ElDescriptionsItem></ElDescriptions><ElSpace class="v1-gap"><ElButton :disabled="!admin" @click="openForm('space')">编辑空间</ElButton><ElButton :disabled="!admin" @click="editTariff">计费设置</ElButton></ElSpace><ArtTable :data="versions" height="260" :show-table-header="false" class="v1-gap"><ElTableColumn label="生效时间"><template #default="{row}">{{row.effective?date(row.effective):'初始版本'}}</template></ElTableColumn><ElTableColumn label="模式"><template #default="{row}">{{({fixed:'固定',time_of_use:'分时',tiered:'阶梯'})[row.tariff.mode]||'分时'}}</template></ElTableColumn><ElTableColumn label="预算 / 元"><template #default="{row}">{{row.tariff.monthly_budget}}</template></ElTableColumn></ArtTable></ElTabPane>
  <ElTabPane label="AI 分析" name="ai"><ElDescriptions :column="2" border><ElDescriptionsItem label="状态"><ElTag :type="aiSettings.enabled?'success':'info'">{{aiSettings.enabled?'已启用':'未启用'}}</ElTag></ElDescriptionsItem><ElDescriptionsItem label="模型">{{aiSettings.model||'未配置'}}</ElDescriptionsItem><ElDescriptionsItem label="近期数据">{{aiSettings.days||14}} 天</ElDescriptionsItem><ElDescriptionsItem label="密钥">{{aiSettings.has_key?'已加密保存':'未保存密钥'}}</ElDescriptionsItem><ElDescriptionsItem label="接口" :span="2"><ElText>{{aiSettings.endpoint||'未配置'}}</ElText></ElDescriptionsItem></ElDescriptions><ElSpace class="v1-gap"><ElButton type="primary" :disabled="user.role!=='admin'" @click="editAI">配置 AI 接口</ElButton><ElButton @click="$emit('navigate','prediction')">前往 AI 分析</ElButton></ElSpace></ElTabPane>
  <ElTabPane label="通知渠道" name="notifications"><ElButton :disabled="user.role!=='admin'" type="primary" @click="openForm('channel')">新增渠道</ElButton><ArtTable :data="channels" height="260" :show-table-header="false" class="v1-gap"><ElTableColumn prop="name" label="渠道" /><ElTableColumn label="类型"><template #default="{row}">{{({webhook:'通用 Webhook',feishu:'飞书机器人',smtp:'SMTP 邮件'})[row.kind]||row.kind}}</template></ElTableColumn><ElTableColumn label="操作"><template #default="{row}"><ElButton text @click="editChannel(row)">编辑</ElButton><ElButton text @click="testChannel(row)">发送测试</ElButton></template></ElTableColumn></ArtTable><ElDivider>发送记录</ElDivider><ArtTable :data="deliveries" height="300" :show-table-header="false"><ElTableColumn label="时间" min-width="180"><template #default="{row}">{{date(row.created)}}</template></ElTableColumn><ElTableColumn label="状态"><template #default="{row}"><ElTag :type="row.state==='sent'?'success':row.state==='failed'?'danger':'warning'">{{({sent:'已发送',queued:'排队',retry:'重试中',failed:'失败'})[row.state]}}</ElTag></template></ElTableColumn><ElTableColumn prop="attempts" label="尝试次数" /><ElTableColumn prop="error" label="结果" min-width="180" /><ElTableColumn label="操作"><template #default="{row}"><ElButton v-if="row.state==='failed'" text @click="retry(row)">重试</ElButton></template></ElTableColumn></ArtTable></ElTabPane>
  <ElTabPane label="账户与网关" name="access"><ElSpace><ElButton :disabled="user.role!=='admin'" @click="openForm('member')">添加成员</ElButton><ElButton :disabled="user.role!=='admin'" @click="openForm('gateway')">登记网关</ElButton></ElSpace><ArtTable :data="system.users||[]" height="250" :show-table-header="false" class="v1-gap"><ElTableColumn prop="username" label="账户" /><ElTableColumn prop="role" label="角色" /><ElTableColumn label="操作"><template #default="{row}"><ElButton text @click="editMember(row)">权限与密码</ElButton></template></ElTableColumn></ArtTable><ElDivider>网关</ElDivider><ArtTable :data="system.gateways||[]" height="250" :show-table-header="false"><ElTableColumn prop="name" label="网关" /><ElTableColumn label="状态"><template #default="{row}">{{row.enabled?'启用':'停用'}}</template></ElTableColumn><ElTableColumn label="操作" min-width="200"><template #default="{row}"><ElButton text @click="gatewayUpdate(row,true)">轮换令牌</ElButton><ElButton text type="danger" @click="gatewayUpdate(row,false)">{{row.enabled?'停用':'启用'}}</ElButton></template></ElTableColumn></ArtTable></ElTabPane>
  <ElTabPane label="运行与维护" name="backend"><ElDescriptions :column="2" border><ElDescriptionsItem label="版本">v{{system.version}}</ElDescriptionsItem><ElDescriptionsItem label="采集心跳">{{date(system.heartbeat)}}</ElDescriptionsItem></ElDescriptions><ElForm label-position="top" class="v1-gap"><ElFormItem label="端口"><ElInputNumber v-model="backend.port" :min="0" :max="65535" :disabled="user.role!=='admin'" /><ElTooltip content="0 为自动分配；重启后生效"><ElButton text circle aria-label="端口说明"><ArtSvgIcon icon="ri:information-line" /></ElButton></ElTooltip></ElFormItem><ElFormItem label="Logo"><ElSpace><ElImage v-if="backend.logo" :src="backend.logo" style="width:48px;height:48px" fit="contain" /><ElUpload :auto-upload="false" accept="image/png,image/jpeg,image/webp" :limit="1" :on-change="uploadLogo" :disabled="user.role!=='admin'"><ElButton>上传 Logo</ElButton></ElUpload></ElSpace></ElFormItem></ElForm><ElButton type="primary" :disabled="user.role!=='admin'" @click="saveBackend">保存设置</ElButton><ElDivider>数据维护</ElDivider><ElSpace><ElButton :disabled="user.role!=='admin'" @click="backup">下载备份</ElButton><ElUpload :auto-upload="false" :limit="1" accept=".sqlite,.sqlite3,.db" :on-change="restoreBackup" :disabled="user.role!=='admin'"><ElButton>恢复备份</ElButton></ElUpload><ElButton type="danger" plain :disabled="user.role!=='admin'" @click="previewReset">恢复出厂设置</ElButton></ElSpace></ElTabPane>
 </ElTabs></ElSpace>
 <ElDrawer v-model="formOpen" :title="formTitle" direction="rtl" size="min(600px,100vw)" :close-on-click-modal="false"><ArtForm :key="formKind+'-'+(draft.id||'new')" ref="formRef" v-model="draft" :items="fields" :span="24" label-position="top" :show-reset="false" :show-submit="false" /><template v-if="formKind==='tariff'"><ElDivider v-if="draft.mode==='time_of_use'">逐小时电价</ElDivider><ElRow v-if="draft.mode==='time_of_use'" :gutter="12"><ElCol v-for="(_,h) in draft.prices" :key="h" :span="8"><ElFormItem :label="String(h).padStart(2,'0')+':00'"><ElInputNumber v-model="draft.prices[h]" :min="0" :max="100" :precision="3" :controls="false" /></ElFormItem></ElCol></ElRow><template v-if="draft.mode==='tiered'"><ElDivider>阶梯</ElDivider><ElRow v-for="(tier,i) in draft.tiers" :key="i" :gutter="12"><ElCol :span="12"><ElFormItem label="累计上限 / kWh"><ElInputNumber v-model="tier.limit" :min="1" /></ElFormItem></ElCol><ElCol :span="12"><ElFormItem label="单价 / 元"><ElInputNumber v-model="tier.price" :min="0" :precision="3" /></ElFormItem></ElCol></ElRow><ElButton @click="draft.tiers.push({limit:(draft.tiers.at(-1)?.limit||0)+200,price:0.8})">添加阶梯</ElButton></template></template><ElAlert v-if="error" :title="error" type="error" :closable="false" /><template #footer><ElButton @click="formOpen=false">取消</ElButton><ElButton type="primary" :loading="busy" @click="saveForm">保存</ElButton></template></ElDrawer>
 <ElDrawer v-model="aiOpen" title="AI 接口配置" direction="rtl" size="min(640px,100vw)" :close-on-click-modal="false" destroy-on-close><ArtForm v-model="aiDraft" :items="aiFields" :span="24" label-position="top" :show-submit="false" :show-reset="false" /><ElAlert v-if="aiConfigError" :title="aiConfigError" type="error" :closable="false" /><template #footer><ElButton @click="aiOpen=false">取消</ElButton><ElButton type="primary" :loading="aiSaving" @click="saveAI">保存配置</ElButton></template></ElDrawer>
 <ElDialog v-model="tokenOpen" title="接入凭据" width="min(640px,94vw)" :close-on-click-modal="false" align-center><ElSpace direction="vertical" fill :size="20" class="v1-dialog-stack"><ElAlert title="令牌只完整显示一次，请立即保存" type="warning" show-icon :closable="false" /><ElDescriptions :column="1" border><ElDescriptionsItem label="网关 ID"><ElInput class="v1-copy-field" :model-value="token.id" readonly><template #append><ElButton @click="copy(token.id,'网关 ID')">复制</ElButton></template></ElInput></ElDescriptionsItem><ElDescriptionsItem label="网关令牌"><ElInput class="v1-copy-field" :model-value="token.token" type="password" show-password readonly><template #append><ElButton @click="copy(token.token,'网关令牌')">复制</ElButton></template></ElInput></ElDescriptionsItem></ElDescriptions></ElSpace><template #footer><ElButton type="primary" @click="tokenOpen=false">我已保存</ElButton></template></ElDialog>
 <ElDialog v-model="resetOpen" class="v1-reset-dialog" title="恢复出厂设置" width="min(640px,94vw)" :close-on-click-modal="false" align-center><ElSpace direction="vertical" fill :size="20" class="v1-dialog-stack"><ElAlert title="以下记录将被永久删除" type="error" show-icon :closable="false" /><ElDescriptions :column="2" border><ElDescriptionsItem v-for="(value,key) in reset.records" :key="key" :label="resetNames[key]||key">{{value}}</ElDescriptionsItem></ElDescriptions><ElForm label-position="top"><ElFormItem label="输入：恢复出厂设置"><ElInput v-model="resetConfirmation" /></ElFormItem><ElFormItem label="管理员密码"><ElInput v-model="resetPassword" type="password" show-password /></ElFormItem></ElForm><ElAlert v-if="error" :title="error" type="error" :closable="false" /></ElSpace><template #footer><ElButton @click="resetOpen=false">取消</ElButton><ElButton type="danger" :disabled="resetConfirmation!=='恢复出厂设置'" :loading="busy" @click="factoryReset">确认清空</ElButton></template></ElDialog>
</template>
<script setup>
import {ref,computed,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {api,n,date,csrf} from './api';
const props=defineProps({space:Object,user:Object});const emit=defineEmits(['refresh','session','navigate']);const system=ref({}),tab=ref('space'),versions=ref([]),channels=ref([]),deliveries=ref([]),backend=ref({port:0}),formOpen=ref(false),formKind=ref(''),draft=ref({}),error=ref(''),busy=ref(false),formRef=ref(),token=ref({}),tokenOpen=ref(false),reset=ref({}),resetOpen=ref(false),resetConfirmation=ref(''),resetPassword=ref('');const admin=computed(()=>['admin','demo'].includes(props.user.role));const f=(key,label,type='input',props={})=>({key,label,type,props});const roles=[{value:'viewer',label:'查看者'},{value:'operator',label:'操作员'},{value:'admin',label:'管理员'},{value:'disabled',label:'停用'}];const names={owner:'建立管理员',space:'编辑空间',member:'添加成员',memberEdit:'账户权限',gateway:'登记网关',channel:'通知渠道',tariff:'计费设置'};const formTitle=computed(()=>names[formKind.value]);
const fields=computed(()=>{switch(formKind.value){case 'owner':return [f('username','账户'),f('password','密码','input',{type:'password',showPassword:true})];case 'space':return [f('name','空间名称')];case 'member':case 'memberEdit':return [f('username','账户','input',{disabled:formKind.value==='memberEdit'}),f('password',formKind.value==='member'?'初始密码':'新密码','input',{type:'password',showPassword:true}),f('role','角色','select',{options:roles.filter(r=>formKind.value==='memberEdit'||r.value!=='disabled')}),...(formKind.value==='memberEdit'?[f('spaces','空间授权','select',{multiple:true,options:allSpaces.value.map(s=>({value:s.id,label:s.name}))})]:[])];case 'gateway':return [f('name','网关名称')];case 'channel':return [f('enabled','启用','switch'),f('name','名称'),f('kind','类型','select',{options:[{value:'webhook',label:'通用 Webhook'},{value:'feishu',label:'飞书机器人'},{value:'smtp',label:'SMTP 邮件'}]}),...(draft.value.kind==='smtp'?[f('config.host','SMTP 主机'),f('config.port','端口','number',{min:1,max:65535}),f('config.ssl','SSL','switch'),f('config.username','账户'),f('config.password','密码','input',{type:'password',showPassword:true}),f('config.sender','发件人'),f('config.recipients','收件人')]:[f('config.url',draft.value.kind==='feishu'?'飞书 Webhook URL':'Webhook URL'),...(draft.value.kind==='feishu'?[f('config.secret','签名密钥（选填）','input',{type:'password',showPassword:true,placeholder:'编辑时留空保留已有密钥'})]:[])]),f('config.space_id','空间','select',{clearable:true,options:allSpaces.value.map(s=>({value:s.id,label:s.name}))}),f('config.level','级别','select',{clearable:true,options:[{value:'warning',label:'预警'},{value:'critical',label:'紧急'}]}),f('config.start','接收开始','timepicker',{format:'HH:mm',valueFormat:'HH:mm'}),f('config.end','接收结束','timepicker',{format:'HH:mm',valueFormat:'HH:mm'})];case 'tariff':return [f('mode','模式','select',{options:[{value:'fixed',label:'固定'},{value:'time_of_use',label:'分时'},{value:'tiered',label:'阶梯'}]}),...(draft.value.mode==='fixed'?[f('fixed_price','单价 / 元','number',{min:0,max:100,precision:3})]:[]),f('monthly_budget','月度预算 / 元','number',{min:0}),f('effective_at','生效时间','datetime',{type:'datetime',valueFormat:'X'})];default:return []}});const aiSettings=ref({}),aiDraft=ref({}),aiOpen=ref(false),aiSaving=ref(false),aiConfigError=ref('');const aiFields=[f('enabled','启用 AI 分析','switch'),f('endpoint','接口地址','input',{placeholder:'完整 Chat Completions 地址或 Base URL'}),f('model','模型名称'),f('api_key','API Key','input',{type:'password',showPassword:true,placeholder:'留空保留现有密钥'}),f('remove_key','清除已保存密钥','switch'),f('prompt','预设提示词','input',{type:'textarea',rows:8,maxlength:8000,showWordLimit:true}),f('days','近期数据范围','select',{options:[7,14,30].map(value=>({value,label:value+' 天'}))}),f('include_names','发送空间与设备原名','switch'),f('max_tokens','最大输出 Token','number',{min:128,max:8192,step:128}),f('token_parameter','输出上限参数','select',{options:[{value:'max_tokens',label:'max_tokens'},{value:'max_completion_tokens',label:'max_completion_tokens'}]}),f('timeout','超时 / 秒','number',{min:10,max:120})];const allSpaces=ref([]);const resetNames={ai_runs:'AI 分析记录',spaces:'空间',settings:'系统与外观设置',audit:'审计日志',scopes:'统计范围版本',tariff_versions:'电价版本',rules:'预警规则',rule_state:'规则运行状态',incident_notes:'事件说明与照片',cameras:'监控配置',api_attempts:'接口请求记录',space_members:'空间授权',recharges:'充值识别',devices:'设备',samples:'明细采样',hourly:'小时用量',api_readings:'接口读数',api_devices:'接口凭据',alerts:'告警',commands:'控制记录',schedules:'计划',gateways:'网关',users:'账户',channels:'通知渠道',deliveries:'发送记录'};
async function load(){try{system.value=await api('system');allSpaces.value=(await api('spaces')).spaces;versions.value=(await api('tariff-versions?space_id='+props.space.id)).versions;if(props.user.role==='admin'){const [c,d,b,ai]=await Promise.all([api('channels'),api('deliveries'),api('backend-settings'),api('ai-settings')]);aiSettings.value=ai.settings;channels.value=c.channels;deliveries.value=d.deliveries;backend.value=b.settings}}catch(e){ElMessage.error(e.message)}}
function openForm(kind){formKind.value=kind;error.value='';draft.value=kind==='space'?{name:props.space.name}:kind==='channel'?{name:'',kind:'webhook',enabled:true,config:{ssl:true,port:465,start:'00:00',end:'23:59'}}:kind==='member'?{username:'',password:'',role:'viewer'}:{};formOpen.value=true}
function editMember(row){formKind.value='memberEdit';draft.value={...row,password:'',spaces:row.spaces||[]};error.value='';formOpen.value=true}function editTariff(){formKind.value='tariff';draft.value={...JSON.parse(JSON.stringify(props.space.tariff)),mode:props.space.tariff.mode||'time_of_use',fixed_price:props.space.tariff.prices[0],tiers:JSON.parse(JSON.stringify(props.space.tariff.tiers||null))||[{limit:200,price:.6},{limit:400,price:.8}],effective_at:undefined};error.value='';formOpen.value=true}
async function saveForm(){busy.value=true;error.value='';try{const kind=formKind.value;if(kind==='owner'){await api('setup',draft.value);emit('session')}else if(kind==='space')await api('spaces',{...draft.value,id:props.space.id});else if(kind==='member')await api('users',draft.value);else if(kind==='memberEdit')await api('member-update',draft.value);else if(kind==='gateway'){token.value=await api('gateways',{...draft.value,space_id:props.space.id});tokenOpen.value=true}else if(kind==='channel')await api('channels',draft.value);else if(kind==='tariff'){const {effective_at,...tariff}=draft.value;await api('tariff',{space_id:props.space.id,tariff,effective_at:effective_at?Number(effective_at):undefined})}formOpen.value=false;emit('refresh');await load();ElMessage.success('已保存')}catch(e){error.value=e.message}finally{busy.value=false}}
async function editChannel(row){try{draft.value=(await api('channel-config?id='+row.id)).channel;formKind.value='channel';error.value='';formOpen.value=true}catch(e){ElMessage.error(e.message)}}
async function testChannel(row){try{await api('channel-test',{id:row.id});ElMessage.success('已加入发送队列');await load()}catch(e){ElMessage.error(e.message)}}async function retry(row){try{await api('delivery-retry',{id:row.id});await load()}catch(e){ElMessage.error(e.message)}}
async function gatewayUpdate(row,rotate){try{await ElMessageBox.confirm(rotate?'轮换后原令牌立即失效。':'更改网关接入状态？','网关设置',{type:'warning'});const r=await api('gateway-update',{id:row.id,rotate,enabled:rotate?!!row.enabled:!row.enabled});if(r.token){token.value={id:row.id,token:r.token};tokenOpen.value=true}await load()}catch(e){if(e?.message)ElMessage.error(e.message)}}
function uploadLogo(file){if(file.size>128*1024){ElMessage.error('Logo 应小于128KB');return}const reader=new FileReader();reader.onload=()=>backend.value.logo=reader.result;reader.readAsDataURL(file.raw)}async function saveBackend(){try{await api('backend-settings',backend.value);ElMessage.success('已保存，端口重启后生效');emit('refresh')}catch(e){ElMessage.error(e.message)}}
async function previewReset(){try{reset.value=await api('reset-preview',{});resetConfirmation.value='';resetPassword.value='';error.value='';resetOpen.value=true}catch(e){ElMessage.error(e.message)}}
async function factoryReset(){busy.value=true;try{await api('factory-reset',{token:reset.value.token,confirmation:resetConfirmation.value,password:resetPassword.value});resetPassword.value='';location.reload()}catch(e){error.value=e.message}finally{busy.value=false}}
function editAI(){aiDraft.value={...JSON.parse(JSON.stringify(aiSettings.value)),api_key:'',remove_key:false};aiConfigError.value='';aiOpen.value=true}
async function saveAI(){aiSaving.value=true;aiConfigError.value='';try{await api('ai-settings',aiDraft.value);aiDraft.value.api_key='';aiOpen.value=false;await load();ElMessage.success('AI 配置已保存')}catch(e){aiConfigError.value=e.message}finally{aiSaving.value=false}}
function backup(){location.href='/api/backup'}
async function copy(value,label='内容'){try{await navigator.clipboard.writeText(String(value||''));ElMessage.success(label+'已复制')}catch{ElMessage.error('复制失败，请手动选择复制')}}
async function restoreBackup(file){try{await ElMessageBox.confirm('备份将覆盖当前账户、设备和历史记录。','恢复备份',{type:'warning'});if(file.size>32*1024*1024)throw Error('备份文件不能超过32MB');const reader=new FileReader();reader.onload=async()=>{try{await api('restore',{data:reader.result.split(',')[1],confirmation:'恢复备份'});location.reload()}catch(e){ElMessage.error(e.message)}};reader.readAsDataURL(file.raw)}catch(e){if(e?.message)ElMessage.error(e.message)}}onMounted(load);
</script>
